head.script:
scwin.screenId = "jldstf07403";

///////// 1. 변수 및 선언 영역 /////////

scwin.grd_Grid = $c.util.getComponent('grd_Grid');

scwin.btn_Excel = $c.util.getComponent('btn_Excel');

scwin.btn_New = $c.util.getComponent('btn_New');

scwin.panel_page = $c.util.getComponent('panel_page');

scwin.btn_Modify = $c.util.getComponent('btn_Modify');

scwin.btn_Delete = $c.util.getComponent('btn_Delete');

scwin.btn_Select = $c.util.getComponent('btn_Select');

scwin.vScrenID = "ULDSTF07403.gfm";

scwin.isSetPopup = false;

scwin.isMailPopup = true;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchCode();
        await scwin.grdSearchCode();
        await scwin.listSync();
        const parentWin = $c.frame.Provider("../");
        const parScrenId = parentWin.vScrenID;
        if (parScrenId === "ULDSTF07041.gfm" || parScrenId === "ULDSTF07404.gfm") {
            scwin.isSetPopup = true;
            scwin.setPar = parentWin.fn_SetPar;
            $c.fil.showObj(scwin.btn_New, false);
            $c.fil.showObj(scwin.btn_Delete, false);
            $c.fil.showObj(scwin.btn_Modify, false);
            $c.fil.showObj(scwin.btn_Excel, false);
        }
        if (parScrenId !== "ULDSTF07404.gfm") {
            console.warn('[sdd] 미포팅 대입 — 아래 주석의 대상'); /* 미포팅 대입 대상: grd_Grid.getColumnInfo("CHK_YN", "Show") */
            $c.fil.showObj(scwin.btn_Select, false);
            scwin.isMailPopup = false;
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07403.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');

scwin.dts_Cod = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cod')) : $c.util.getComponent('dts_Cod');

scwin.pMenuID = undefined; try { scwin.pMenuID = /* sdd-asis-lifecycle:begin pMenuID — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.win.getProgramId()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07403' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07403.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

