*/
scwin.btn_Excel_onclick = async function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Excel_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (scwin.dts_List.CountRow > 0) {
            $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07);
            scwin.grd_Grid.GridToOffice("평가기관담당자", "", 8, 0);
        } else {
            await $c.win.alert($c.lc.NO_EXCEL_DATA);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07403.btn_Excel_onclick' }); }
};

