*/
scwin.grd_Grid_ondblclick = function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin grd_Grid_ondblclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (scwin.isSetPopup && !scwin.isMailPopup) {
            const arrPar = new Array();
            if (scwin.setPar != null) {
                arrPar[0] = scwin.dts_List.getCellData(scwin.dts_List.getRowPosition(), 'CHRG_NM');
                arrPar[1] = scwin.dts_List.getCellData(scwin.dts_List.getRowPosition(), 'COM_TEL_NO');
                arrPar[2] = scwin.dts_List.getCellData(scwin.dts_List.getRowPosition(), 'CHRG_EMAIL');
                scwin.setPar(arrPar);
            }
            $c.frame.CloseFrame();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07403.grd_Grid_ondblclick' }); }
};

