/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) {
            return;
        }
        scwin.fn_trs($c.fil.TR_JOB_INSERT);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkForm = async function () {
    /* sdd-asis-lifecycle:begin checkForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 1, j = scwin.dts_List.CountRow; i <= j; i++) {
        const status = scwin.dts_List.getRowStatus(i);
        if (status == 1 || status == 3) {
            if (scwin.dts_List.getCellData(i, "SPECY_VALU_INST_CD") === "") {
                await $c.win.alert(i + "번째행" + " 기관명은 필수값입니다.");
                return false;
            }
            if (scwin.dts_List.getCellData(i, "SPECY_VALU_INST_TP_CD") === "") {
                await $c.win.alert(i + "번째행" + " 구분값은 필수값입니다.");
                return false;
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkSelect
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkSelect = function () {
    /* sdd-asis-lifecycle:begin fn_chkSelect — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let arrPar;
    let selNum = 0;
    let isFirst = true;
    for (let i = 1, j = scwin.dts_List.CountRow; i <= j; i++) {
        if (scwin.dts_List.getCellData(i, "CHK_YN") === "T") {
            arrPar = new Array();
            arrPar[0] = scwin.dts_List.getCellData(i, 'CHRG_NM');
            arrPar[1] = scwin.dts_List.getCellData(i, 'CHRG_EMAIL');
            selNum++;
            if (scwin.setPar != null) {
                if (selNum != 1) {
                    isFirst = false;
                }
                scwin.setPar(arrPar, isFirst);
            }
        }
    }
    $c.frame.CloseFrame();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setPar
 * @author Inswave
 * @date 2026. 09. 29
 * @param arrPar
 * @returns
 * @hidden N
*/
scwin.setPar = function (arrPar) {
    /* sdd-asis-lifecycle:begin fn_SetPar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    txb_ISUR_CD.value = arrPar[0].ISUR_CD;
    txb_COM_NM.value = arrPar[0].COM_NM;
    /* sdd-asis-lifecycle:end */
};


